1	'use server'
2	
3	import { revalidatePath } from 'next/cache'
4	import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
5	import { logger } from '@/lib/logger'
6	import {
7	  createProject,
8	  updateProject,
9	  completeProject,
10	  archiveProject,
11	  linkBookingToProject,
12	  unlinkBookingFromProject,
13	  addProjectReference,
14	  removeProjectReference,
15	  reorderProjectReferences,
16	  addProgressPhoto,
17	  removeProgressPhoto,
18	  recordDepositToProject,
19	  allocateDepositToSession,
20	} from '@/lib/projects/mutations'
21	import {
22	  projectCreateSchema,
23	  projectUpdateSchema,
24	  addReferenceSchema,
25	  addProgressPhotoSchema,
26	  allocateDepositSchema,
27	} from '@/lib/projects/schemas'
28	
29	type ActionResult<T = void> =
30	  | { ok: true; data: T }
31	  | { ok: false; error: string }
32	
33	type MutationRole = 'owner' | 'admin' | 'artist'
34	type ReadRole = 'owner' | 'admin' | 'artist' | 'receptionist' | 'guest_artist'
35	
36	function canWrite(role: ReadRole): role is MutationRole {
37	  return role === 'owner' || role === 'admin' || role === 'artist'
38	}
39	
40	function canAdmin(role: ReadRole): boolean {
41	  return role === 'owner' || role === 'admin'
42	}
43	
44	// ─── Create ────────────────────────────────────────────────────────────────────
45	
46	export async function createProjectAction(
47	  formData: FormData
48	): Promise<ActionResult<{ id: string }>> {
49	  const auth = await getAuthenticatedUser()
50	  if (!auth) return { ok: false, error: 'Not authenticated' }
51	
52	  const role = auth.role as ReadRole
53	  // Receptionist can create projects per RLS
54	  if (role === 'guest_artist') return { ok: false, error: 'Insufficient permissions' }
55	
56	  const raw = {
57	    clientId: formData.get('clientId'),
58	    name: formData.get('name'),
59	    description: formData.get('description') || undefined,
60	    placement: formData.get('placement') || undefined,
61	    style: formData.get('style') || undefined,
62	    primaryArtistId: formData.get('primaryArtistId') || undefined,
63	    totalSessionsPlanned: formData.get('totalSessionsPlanned')
64	      ? Number(formData.get('totalSessionsPlanned'))
65	      : undefined,
66	    totalPriceCents: formData.get('totalPriceCents')
67	      ? Number(formData.get('totalPriceCents'))
68	      : 0,
69	    moodboardUrl: formData.get('moodboardUrl') || undefined,
70	    initialDepositCents: formData.get('initialDepositCents')
71	      ? Number(formData.get('initialDepositCents'))
72	      : undefined,
73	  }
74	
75	  const parsed = projectCreateSchema.safeParse(raw)
76	  if (!parsed.success) {
77	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
78	  }
79	
80	  try {
81	    const project = await createProject(auth.studioId, parsed.data)
82	    revalidatePath('/projects')
83	    return { ok: true, data: { id: project.id } }
84	  } catch (err) {
85	    logger.error({ err }, 'createProjectAction failed')
86	    return { ok: false, error: 'Failed to create project' }
87	  }
88	}
89	
90	// ─── Update ────────────────────────────────────────────────────────────────────
91	
92	export async function updateProjectAction(
93	  id: string,
94	  formData: FormData
95	): Promise<ActionResult<void>> {
96	  const auth = await getAuthenticatedUser()
97	  if (!auth) return { ok: false, error: 'Not authenticated' }
98	  if (!canWrite(auth.role as ReadRole)) return { ok: false, error: 'Insufficient permissions' }
99	
100	  const raw = {
101	    name: formData.get('name') || undefined,
102	    description: formData.get('description') ?? undefined,
103	    placement: formData.get('placement') ?? undefined,
104	    style: formData.get('style') ?? undefined,
105	    primaryArtistId: formData.get('primaryArtistId') ?? undefined,
106	    totalSessionsPlanned: formData.get('totalSessionsPlanned')
107	      ? Number(formData.get('totalSessionsPlanned'))
108	      : undefined,
109	    totalPriceCents: formData.get('totalPriceCents')
110	      ? Number(formData.get('totalPriceCents'))
111	      : undefined,
112	    moodboardUrl: formData.get('moodboardUrl') ?? undefined,
113	    status: formData.get('status') ?? undefined,
114	  }
115	
116	  const parsed = projectUpdateSchema.safeParse(raw)
117	  if (!parsed.success) {
118	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
119	  }
120	
121	  try {
122	    await updateProject(auth.studioId, id, parsed.data)
123	    revalidatePath('/projects')
124	    revalidatePath(`/projects/${id}`)
125	    return { ok: true, data: undefined }
126	  } catch (err) {
127	    logger.error({ err, id }, 'updateProjectAction failed')
128	    return { ok: false, error: 'Failed to update project' }
129	  }
130	}
131	
