150	// ─── Archive ───────────────────────────────────────────────────────────────────
151	
152	export async function archiveProjectAction(id: string): Promise<ActionResult<void>> {
153	  const auth = await getAuthenticatedUser()
154	  if (!auth) return { ok: false, error: 'Not authenticated' }
