const recordDepositTransactionSchema = z.object({
  amount_cents: z.number().int().positive(),
  method: z.enum(['stripe', 'cash', 'card', 'other']).optional(),
  note: z.string().max(500).optional(),
})

export async function updateProjectStatusAction(
  projectId: string,
  newStatus: ProjectStatus
): Promise<ActionResult<void>> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }
  if (!canWrite(auth.role as ReadRole)) return { ok: false, error: 'Insufficient permissions' }

  const supabase = await createClient()

  // Fetch current status for the activity log
  const { data: current, error: fetchErr } = await supabase
    .from('projects')
    .select('status')
    .eq('id', projectId)
    .eq('studio_id', auth.studioId)
    .single()

  if (fetchErr || !current) {
    return { ok: false, error: 'Project not found' }
  }

  const prevStatus = current.status

  // Update status
  const { error: updateErr } = await supabase
    .from('projects')
    .update({ status: newStatus, updated_at: new Date().toISOString() })
    .eq('id', projectId)
    .eq('studio_id', auth.studioId)

  if (updateErr) {
    logger.error({ updateErr, projectId }, 'updateProjectStatusAction update failed')
    return { ok: false, error: 'Failed to update status' }
  }

  // Append activity log row
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  await (supabase as any)
    .from('project_activity_log')
    .insert({
      project_id: projectId,
      actor_id: auth.userId,
      event_type: 'status_changed',
      details: { prev_status: prevStatus, new_status: newStatus },
    })

  revalidatePath('/projects')
  revalidatePath(`/projects/${projectId}`)
  return { ok: true, data: undefined }
}

export async function recordDepositTransactionAction(
  projectId: string,
  input: { amount_cents: number; method?: string; note?: string }
): Promise<ActionResult<void>> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }
  if (!canAdmin(auth.role as ReadRole)) return { ok: false, error: 'Only owners and admins can record deposits' }

  const parsed = recordDepositTransactionSchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
  }

  const supabase = await createClient()

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const { error } = await (supabase as any)
    .from('project_deposit_transactions')
    .insert({
      project_id: projectId,
      type: 'received',
      amount_cents: parsed.data.amount_cents,
      method: parsed.data.method ?? null,
      note: parsed.data.note ?? null,
      created_by: auth.userId,
    })

  if (error) {
    logger.error({ error, projectId }, 'recordDepositTransactionAction failed')
    return { ok: false, error: 'Failed to record deposit' }
  }

  // Append activity log
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  await (supabase as any)
    .from('project_activity_log')
    .insert({
      project_id: projectId,
      actor_id: auth.userId,
      event_type: 'deposit_received',
      details: { amount_cents: parsed.data.amount_cents, method: parsed.data.method ?? null },
    })

  revalidatePath(`/projects/${projectId}`)
  return { ok: true, data: undefined }
}

export async function applyDepositToSessionAction(
  projectId: string,
  bookingId: string,
  amountCents: number
): Promise<ActionResult<void>> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }
  if (!canAdmin(auth.role as ReadRole)) return { ok: false, error: 'Only owners and admins can apply deposits' }

  if (amountCents <= 0) return { ok: false, error: 'Amount must be positive' }

  const supabase = await createClient()

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const { error } = await (supabase as any)
    .from('project_deposit_transactions')
    .insert({
      project_id: projectId,
      type: 'applied',
      amount_cents: amountCents,
      applied_to_session_id: bookingId,
      created_by: auth.userId,
    })

  if (error) {
    logger.error({ error, projectId, bookingId }, 'applyDepositToSessionAction failed')
    return { ok: false, error: 'Failed to apply deposit' }
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  await (supabase as any)
    .from('project_activity_log')
    .insert({
      project_id: projectId,
      actor_id: auth.userId,
      event_type: 'deposit_applied',
      details: { amount_cents: amountCents, booking_id: bookingId },
    })

  revalidatePath(`/projects/${projectId}`)
  return { ok: true, data: undefined }
}

export async function consumeDepositAction(
  projectId: string,
  note?: string
): Promise<ActionResult<void>> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }
  if (!canAdmin(auth.role as ReadRole)) return { ok: false, error: 'Only owners and admins can consume deposits' }

  const supabase = await createClient()

  // Fetch current pool to consume it
  const { data: proj } = await supabase
    .from('projects')
    .select('deposit_pool_cents')
    .eq('id', projectId)
    .eq('studio_id', auth.studioId)
    .single()

  if (!proj || proj.deposit_pool_cents <= 0) {
    return { ok: false, error: 'No deposit balance to consume' }
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const { error } = await (supabase as any)
    .from('project_deposit_transactions')
    .insert({
      project_id: projectId,
      type: 'consumed',
      amount_cents: proj.deposit_pool_cents,
      note: note ?? null,
      created_by: auth.userId,
    })

  if (error) {
    logger.error({ error, projectId }, 'consumeDepositAction failed')
    return { ok: false, error: 'Failed to consume deposit' }
  }

  revalidatePath(`/projects/${projectId}`)
  return { ok: true, data: undefined }
}

export async function refundDepositAction(
  projectId: string,
  amountCents: number
): Promise<ActionResult<void>> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }
  if (!canAdmin(auth.role as ReadRole)) return { ok: false, error: 'Only owners and admins can refund deposits' }

  if (amountCents <= 0) return { ok: false, error: 'Amount must be positive' }

  const supabase = await createClient()

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const { error } = await (supabase as any)
    .from('project_deposit_transactions')
    .insert({
      project_id: projectId,
      type: 'refunded',
      amount_cents: amountCents,
      created_by: auth.userId,
    })

  if (error) {
    logger.error({ error, projectId }, 'refundDepositAction failed')
    return { ok: false, error: 'Failed to record refund' }
  }

  revalidatePath(`/projects/${projectId}`)
  return { ok: true, data: undefined }
}

export async function addProjectNoteAction(
  projectId: string,
  body: string
): Promise<ActionResult<void>> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }

  if (!body.trim()) return { ok: false, error: 'Note cannot be empty' }

  const supabase = await createClient()

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const { error } = await (supabase as any)
    .from('project_activity_log')
    .insert({
      project_id: projectId,
      actor_id: auth.userId,
      event_type: 'note_added',
      details: { body: body.trim() },
    })

  if (error) {
    logger.error({ error, projectId }, 'addProjectNoteAction failed')
    return { ok: false, error: 'Failed to add note' }
  }

  revalidatePath(`/projects/${projectId}`)
  return { ok: true, data: undefined }
}

