    dotClass: 'bg-[var(--color-warning)]',
    pillClass: 'bg-[var(--color-warning-bg)] text-[var(--color-warning-foreground)]',
  },
  cancelled: {
    label: 'Cancelled',
    dotClass: 'bg-[var(--color-stone)]/50',
    pillClass: 'bg-[var(--color-stone)]/10 text-[var(--color-stone)]',
  },
}

const ALL_STATUSES: ProjectStatus[] = [
  'planning',
  'deposit_paid',
  'active',
  'healing',
  'completed',
  'on_hold',
  'cancelled',
]

// ─── Size labels ───────────────────────────────────────────────────────────────

const SIZE_LABELS: Record<string, string> = {
  small: 'Small',
  medium: 'Medium',
  large: 'Large',
  extra_large: 'XL',
  full_sleeve: 'Full sleeve',
  full_back: 'Full back',
}

const COLOR_MODE_LABELS: Record<string, string> = {
  color: 'Color',
  black_and_grey: 'B&G',
  both: 'Color + B&G',
}

// ─── Inline-editable name ──────────────────────────────────────────────────────

function EditableName({
  name,
  projectId,
  canEdit,
  onRefresh,
}: {
  name: string
  projectId: string
  canEdit: boolean
  onRefresh: () => void
}) {
  const [editing, setEditing] = useState(false)
  const [value, setValue] = useState(name)
  const [isPending, startTransition] = useTransition()
  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    if (editing) inputRef.current?.focus()
  }, [editing])

  const commit = () => {
    const trimmed = value.trim()
    if (!trimmed || trimmed === name) {
      setValue(name)
      setEditing(false)
      return
    }
    const fd = new FormData()
    fd.set('name', trimmed)
    startTransition(async () => {
      const result = await updateProjectAction(projectId, fd)
      if (!result.ok) {
        toast.error(result.error)
        setValue(name)
      } else {
        onRefresh()
      }
      setEditing(false)
    })
  }

  if (!canEdit) {
    return (
      <h1 className="font-serif italic text-[2.25rem] leading-tight text-[var(--color-onyx)] tracking-tight">
        {name}
      </h1>
    )
  }

  return editing ? (
    <input
      ref={inputRef}
      value={value}
      onChange={(e) => setValue(e.target.value)}
      onBlur={commit}
      onKeyDown={(e) => {
        if (e.key === 'Enter') commit()
        if (e.key === 'Escape') { setValue(name); setEditing(false) }
      }}
      disabled={isPending}
      className={cn(
        'font-serif italic text-[2.25rem] leading-tight text-[var(--color-onyx)] tracking-tight',
        'bg-transparent border-b border-[var(--color-stone)] outline-none w-full min-w-0',
        'focus:border-[var(--color-onyx)]',
      )}
    />
  ) : (
    <button
      onClick={() => setEditing(true)}
      className="group flex items-start gap-2 text-left"
      aria-label="Edit project name"
    >
      <h1 className="font-serif italic text-[2.25rem] leading-tight text-[var(--color-onyx)] tracking-tight">
        {name}
      </h1>
      <Pencil className="h-4 w-4 text-[var(--color-stone)] opacity-0 group-hover:opacity-100 mt-2 shrink-0 transition-opacity" />
    </button>
  )
}

// ─── Status dropdown ───────────────────────────────────────────────────────────

function StatusPill({
  status,
  projectId,
  canEdit,
  onRefresh,
}: {
  status: ProjectStatus
  projectId: string
  canEdit: boolean
  onRefresh: () => void
}) {
  const [isPending, startTransition] = useTransition()
  const cfg = STATUS_CONFIGS[status] ?? STATUS_CONFIGS.active

  const handleChange = (next: ProjectStatus) => {
    if (next === status) return
    startTransition(async () => {
      const result = await updateProjectStatusAction(projectId, next)
      if (!result.ok) {
        toast.error(result.error)
      } else {
        toast.success(`Status updated to ${STATUS_CONFIGS[next]?.label ?? next}`)
        onRefresh()
      }
    })
  }

  if (!canEdit) {
    return (
      <span className={cn('inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium', cfg.pillClass)}>
        <span className={cn('w-1.5 h-1.5 rounded-full shrink-0', cfg.dotClass)} />
        {cfg.label}
      </span>
    )
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button
            disabled={isPending}
            className={cn(
              'inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium',
              'transition-opacity hover:opacity-80 cursor-pointer',
              cfg.pillClass,
            )}
          >
            <span className={cn('w-1.5 h-1.5 rounded-full shrink-0', cfg.dotClass)} />
            {cfg.label}
          </button>
        }
      />
      <DropdownMenuContent align="start" className="w-44">
        {ALL_STATUSES.map((s) => {
          const c = STATUS_CONFIGS[s] ?? STATUS_CONFIGS.active
          return (
            <DropdownMenuItem
              key={s}
              onClick={() => handleChange(s)}
              className="flex items-center gap-2"
            >
              <span className={cn('w-2 h-2 rounded-full shrink-0', c.dotClass)} />
              {c.label}
              {s === status && <Check className="h-3 w-3 ml-auto text-[var(--color-stone)]" />}
            </DropdownMenuItem>
          )
        })}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

// ─── Stat card ─────────────────────────────────────────────────────────────────

function StatCard({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex flex-col gap-0.5 rounded-lg border border-[var(--color-border)] bg-[var(--color-bone)] px-3 py-2.5 shadow-[var(--shadow-soft)]">
      <span className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)]">
        {label}
      </span>
      <span className="font-serif italic text-[1.375rem] leading-tight text-[var(--color-onyx)] tabular-nums">
        {value}
      </span>
    </div>
  )
}

// ─── Sub-line builder ──────────────────────────────────────────────────────────

function buildSubline(project: ProjectWithSessions): string {
  const parts: string[] = []

  if (project.size) parts.push(SIZE_LABELS[project.size] ?? project.size)
  if (project.placement) parts.push(project.placement)
  if (project.style) parts.push(project.style.replace(/_/g, ' '))
  if (project.color_mode) parts.push(COLOR_MODE_LABELS[project.color_mode] ?? project.color_mode)
  if (project.primary_artist) parts.push(project.primary_artist.display_name)
  if (project.started_at) {
    parts.push(
      `Started ${formatDate(project.started_at, { month: 'short', day: 'numeric', year: 'numeric' })}`
    )
  }

  return parts.join(' · ')
}

// ─── Next session formatter ────────────────────────────────────────────────────

function formatNextSession(session: ProjectSession | null): string {
  if (!session) return '—'
  const d = new Date(session.scheduled_at)
  return formatDate(d, { month: 'short', day: 'numeric' })
}

// ─── Props ────────────────────────────────────────────────────────────────────

interface ProjectHeroProps {
  project: ProjectWithSessions
  nextSession: ProjectSession | null
  role: string
  onRefresh: () => void
  onShowArchive: () => void
}

// ─── Hero ─────────────────────────────────────────────────────────────────────

export function ProjectHero({
  project,
  nextSession,
  role,
  onRefresh,
  onShowArchive,
}: ProjectHeroProps) {
  const router = useRouter()
  const [showDeleteDialog, setShowDeleteDialog] = useState(false)
  const [isPending, startTransition] = useTransition()

  const canWrite = role === 'owner' || role === 'admin' || role === 'artist'
  const canAdmin = role === 'owner' || role === 'admin'

  const sessionCount = project.sessions.length
  const completedCount = project.sessions.filter((s) => s.status === 'completed').length
  const totalPlanned = project.total_sessions_planned

  const sessionsLabel = totalPlanned
    ? `${completedCount}/${totalPlanned}`
    : `${sessionCount}`

  const poolBalance = Math.max(0, project.deposit_pool_cents - project.deposit_applied_cents)

  const subline = buildSubline(project)

  const handleArchive = () => {
    startTransition(async () => {
      const result = await archiveProjectAction(project.id)
      if (!result.ok) {
        toast.error(result.error)
        return
      }
      toast.success('Project archived')
      router.push('/projects')
    })
  }

  return (
    <div className="space-y-4">
      {/* Breadcrumb */}
      <nav className="flex items-center gap-1 text-xs text-[var(--color-stone)]" aria-label="Breadcrumb">
        <Link
          href="/projects"
          className="hover:text-[var(--color-onyx)] transition-colors"
        >
          Projects
        </Link>
        <ChevronRight className="h-3 w-3 shrink-0" />
        <span className="text-[var(--color-onyx)] font-medium truncate max-w-[240px]">
          {project.name}
        </span>
      </nav>

      {/* Status + name row */}
      <div className="flex items-start gap-3 flex-wrap">
        <StatusPill
          status={project.status as ProjectStatus}
          projectId={project.id}
          canEdit={canWrite}
          onRefresh={onRefresh}
        />

        {/* Action strip — right side on desktop */}
        <div className="ml-auto flex items-center gap-1.5 shrink-0">
          <Button
            variant="outline"
            size="sm"
            className="h-7 px-2.5 text-xs gap-1.5"
            onClick={() => toast.info('Client share link — coming in v2')}
          >
            <Share2 className="h-3 w-3" />
            Share
          </Button>
          <Button
            variant="outline"
            size="sm"
            className="h-7 px-2.5 text-xs gap-1.5"
            onClick={() => toast.info('PDF export — coming in v2')}
          >
            <FileDown className="h-3 w-3" />
            Export
          </Button>

          {(canWrite || canAdmin) && (
            <DropdownMenu>
              <DropdownMenuTrigger
                render={
                  <Button
                    variant="outline"
                    size="icon"
                    className="h-7 w-7"
                    aria-label="More options"
                  >
                    <MoreHorizontal className="h-3.5 w-3.5" />
                  </Button>
                }
              />
              <DropdownMenuContent align="end" className="w-40">
                {canWrite && (
                  <DropdownMenuItem onClick={() => onRefresh()}>
                    <Pencil className="h-3.5 w-3.5 mr-2" />
                    Edit details
                  </DropdownMenuItem>
                )}
                {canAdmin && project.status !== 'cancelled' && (
                  <>
                    <DropdownMenuSeparator />
                    <DropdownMenuItem
                      onClick={onShowArchive}
                    >
                      <Archive className="h-3.5 w-3.5 mr-2" />
                      Archive
                    </DropdownMenuItem>
                    <DropdownMenuItem
                      className="text-[var(--color-destructive)] focus:text-[var(--color-destructive)]"
                      onClick={() => setShowDeleteDialog(true)}
                    >
                      <Trash2 className="h-3.5 w-3.5 mr-2" />
                      Delete
                    </DropdownMenuItem>
                  </>
                )}
              </DropdownMenuContent>
            </DropdownMenu>
          )}
        </div>
      </div>

      {/* Project name — inline editable */}
      <EditableName
        name={project.name}
        projectId={project.id}
        canEdit={canWrite}
        onRefresh={onRefresh}
      />

      {/* Sub-line */}
      {subline && (
        <p className="text-sm text-[var(--color-stone)] leading-snug">
          {subline}
        </p>
      )}

      {/* 4-stat row */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-2.5">
        <StatCard
          label="Sessions"
          value={sessionsLabel}
        />
        <StatCard
          label="Next session"
          value={formatNextSession(nextSession)}
        />
        <StatCard
          label="Total price"
          value={project.total_price_cents > 0 ? formatCurrency(project.total_price_cents) : '—'}
        />
        <StatCard
          label="Pool balance"
          value={formatCurrency(poolBalance)}
        />
      </div>

      {/* Delete confirmation */}
      <AlertDialog open={showDeleteDialog} onOpenChange={setShowDeleteDialog}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete this project?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently archive the project. All sessions and photos are preserved.
              This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleArchive}
              disabled={isPending}
              className="bg-[var(--color-destructive)] text-[var(--color-destructive-foreground)] hover:bg-[var(--color-destructive)]/90"
            >
              Archive project
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

