// ─── Deposit ───────────────────────────────────────────────────────────────────

export async function recordDepositAction(
  projectId: string,
  amountCents: number
): Promise<ActionResult<void>> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }
  if (!canAdmin(auth.role as ReadRole)) return { ok: false, error: 'Only owners and admins can record deposits' }

  if (amountCents <= 0) return { ok: false, error: 'Amount must be positive' }

  try {
    await recordDepositToProject(auth.studioId, projectId, amountCents)
    revalidatePath(`/projects/${projectId}`)
    return { ok: true, data: undefined }
  } catch (err) {
    logger.error({ err, projectId }, 'recordDepositAction failed')
    return { ok: false, error: 'Failed to record deposit' }
  }
}

export async function allocateDepositAction(
  projectId: string,
  bookingId: string,
  amountCents: number
): Promise<ActionResult<void>> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }
  if (!canAdmin(auth.role as ReadRole)) return { ok: false, error: 'Only owners and admins can allocate deposits' }

  const parsed = allocateDepositSchema.safeParse({ bookingId, amountCents })
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
  }

  try {
    await allocateDepositToSession(auth.studioId, projectId, bookingId, amountCents)
    revalidatePath(`/projects/${projectId}`)
    return { ok: true, data: undefined }
  } catch (err) {
    logger.error({ err, projectId, bookingId }, 'allocateDepositAction failed')
    const message = err instanceof Error ? err.message : 'Failed to allocate deposit'
    return { ok: false, error: message }
  }
}

