// ─── Deposit apply rule label ──────────────────────────────────────────────────

function ruleLabel(
  rule: 'last_session' | 'split_evenly' | 'manual',
  sessionCount: number
): string {
  if (rule === 'last_session') return 'applies to last session'
  if (rule === 'split_evenly') return `split evenly across ${sessionCount} session${sessionCount !== 1 ? 's' : ''}`
  return 'manual'
}

// ─── Transaction row ───────────────────────────────────────────────────────────

function TxRow({
  tx,
  sessionNumber,
}: {
  tx: ProjectDepositTransactionRow
  sessionNumber?: number | null
}) {
  const isCredit = tx.type === 'received'
  const isDebit = tx.type === 'applied' || tx.type === 'refunded' || tx.type === 'consumed'

  let description = ''
  if (tx.type === 'received') {
    const method = tx.method ? ` · ${tx.method}` : ''
    description = `Deposit received${method}`
  } else if (tx.type === 'applied') {
    const sn = sessionNumber != null ? `S${sessionNumber}` : 'session'
    description = `Applied to ${sn}`
  } else if (tx.type === 'refunded') {
    description = 'Refunded to client'
  } else if (tx.type === 'consumed') {
    description = tx.note ? `No-show write-off · ${tx.note}` : 'No-show write-off'
  }

  const amountStr = formatCurrency(tx.amount_cents)
  const dateStr = formatDate(tx.created_at, { month: 'short', day: 'numeric' })

  return (
    <div className="flex items-center gap-3 py-2.5 border-b border-[var(--color-border)] last:border-0">
      <div className="flex-1 min-w-0">
        <p className="text-xs text-[var(--color-stone)]">{dateStr}</p>
        <p className="text-sm text-[var(--color-bone)] truncate">{description}</p>
        {tx.note && tx.type !== 'consumed' && (
          <p className="text-[11px] text-[var(--color-stone)] truncate">{tx.note}</p>
        )}
      </div>
      <span
        className={cn(
          'text-sm font-semibold tabular-nums shrink-0',
          isCredit && 'text-[var(--color-success-bg)]',
          isDebit && 'text-[var(--color-rust)]',
        )}
      >
        {isCredit ? '+' : '−'}{amountStr}
      </span>
    </div>
  )
}

// ─── Props ────────────────────────────────────────────────────────────────────

interface DepositPoolLedgerProps {
  project: ProjectWithSessions
  transactions: ProjectDepositTransactionRow[]
  canAdmin: boolean
  onRefresh: () => void
}

// ─── Ledger card ──────────────────────────────────────────────────────────────

export function DepositPoolLedger({
  project,
  transactions,
  canAdmin,
  onRefresh,
}: DepositPoolLedgerProps) {
  const [isPending, startTransition] = useTransition()
  const [showRecordDialog, setShowRecordDialog] = useState(false)
  const [showApplyDialog, setShowApplyDialog] = useState(false)
  const [showConsumeDialog, setShowConsumeDialog] = useState(false)
  const [showRefundDialog, setShowRefundDialog] = useState(false)

  // Record deposit form state
  const [recordAmount, setRecordAmount] = useState(0)
  const [recordMethod, setRecordMethod] = useState<'stripe' | 'cash' | 'card' | 'other'>('cash')
  const [recordNote, setRecordNote] = useState('')

  // Apply form state
  const [applyBookingId, setApplyBookingId] = useState('')
  const [applyAmount, setApplyAmount] = useState(0)

  // Consume note
  const [consumeNote, setConsumeNote] = useState('')

  // Refund amount
  const [refundAmount, setRefundAmount] = useState(0)

  const poolBalance = Math.max(0, project.deposit_pool_cents - project.deposit_applied_cents)
  const rule = project.deposit_apply_rule
  const sessionCount = project.sessions.length

  // Sessions not yet applied to
  const appliedSessionIds = transactions
    .filter((t) => t.type === 'applied' && t.applied_to_session_id)
    .map((t) => t.applied_to_session_id)

  const availableSessions = project.sessions.filter(
    (s) => !appliedSessionIds.includes(s.id)
  )

  // Build session number lookup for transaction rows
  const sessionNumberById = Object.fromEntries(
    project.sessions.map((s) => [s.id, s.session_number])
  )

  const handleRecord = () => {
    if (recordAmount <= 0) { toast.error('Amount must be greater than zero'); return }
    startTransition(async () => {
      const result = await recordDepositTransactionAction(project.id, {
        amount_cents: recordAmount,
        method: recordMethod,
        note: recordNote || undefined,
      })
      if (!result.ok) { toast.error(result.error); return }
      toast.success('Deposit recorded')
      setShowRecordDialog(false)
      setRecordAmount(0)
      setRecordNote('')
      onRefresh()
    })
  }

  const handleApply = () => {
    if (!applyBookingId) { toast.error('Select a session'); return }
    if (applyAmount <= 0) { toast.error('Amount must be greater than zero'); return }
    if (applyAmount > poolBalance) { toast.error('Amount exceeds available balance'); return }
    startTransition(async () => {
      const result = await applyDepositToSessionAction(project.id, applyBookingId, applyAmount)
      if (!result.ok) { toast.error(result.error); return }
      toast.success('Deposit applied to session')
      setShowApplyDialog(false)
      setApplyBookingId('')
      setApplyAmount(0)
      onRefresh()
    })
  }

  const handleConsume = () => {
    startTransition(async () => {
      const result = await consumeDepositAction(project.id, consumeNote || undefined)
      if (!result.ok) { toast.error(result.error); return }
      toast.success('Deposit written off')
      setShowConsumeDialog(false)
      setConsumeNote('')
      onRefresh()
    })
  }

  const handleRefund = () => {
    if (refundAmount <= 0) { toast.error('Amount must be greater than zero'); return }
    if (refundAmount > poolBalance) { toast.error('Amount exceeds available balance'); return }
    startTransition(async () => {
      const result = await refundDepositAction(project.id, refundAmount)
      if (!result.ok) { toast.error(result.error); return }
      toast.success('Refund recorded')
      setShowRefundDialog(false)
      setRefundAmount(0)
      onRefresh()
    })
  }

  return (
    <div className="rounded-xl bg-[var(--color-onyx)] text-[var(--color-bone)] p-5 shadow-[var(--shadow-card)] space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <span className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)]">
          Deposit Pool
        </span>
        {canAdmin && (
          <DropdownMenu>
            <DropdownMenuTrigger
              render={
                <button
                  className="p-1 rounded hover:bg-white/10 text-[var(--color-stone)] hover:text-[var(--color-bone)] transition-colors"
                  aria-label="Deposit options"
                >
                  <MoreHorizontal className="h-4 w-4" />
                </button>
              }
            />
            <DropdownMenuContent align="end" className="w-40">
              {poolBalance > 0 && availableSessions.length > 0 && (
                <DropdownMenuItem onClick={() => setShowApplyDialog(true)}>
                  Apply to session
                </DropdownMenuItem>
              )}
              {poolBalance > 0 && (
                <>
                  <DropdownMenuItem onClick={() => { setRefundAmount(poolBalance); setShowRefundDialog(true) }}>
                    Refund
                  </DropdownMenuItem>
                  <DropdownMenuItem
                    className="text-[var(--color-destructive)] focus:text-[var(--color-destructive)]"
                    onClick={() => setShowConsumeDialog(true)}
                  >
                    Consume (no-show)
                  </DropdownMenuItem>
                </>
              )}
            </DropdownMenuContent>
          </DropdownMenu>
        )}
      </div>

      {/* Big balance */}
      <div>
        <div className="font-serif italic text-4xl tabular-nums text-[var(--color-bone)] leading-none">
          {formatCurrency(poolBalance)}
        </div>
        <p className="text-xs text-[var(--color-stone)] mt-1">
          {formatCurrency(project.deposit_pool_cents)} paid ·{' '}
          {formatCurrency(project.deposit_applied_cents)} applied ·{' '}
          {ruleLabel(rule, sessionCount)}
        </p>
      </div>

      {/* Transaction log */}
      {transactions.length > 0 && (
        <div className="border-t border-white/10 pt-3 space-y-0 max-h-48 overflow-y-auto scrollbar-thin scrollbar-thumb-white/10">
          {transactions.map((tx) => (
            <TxRow
              key={tx.id}
              tx={tx}
              sessionNumber={
                tx.applied_to_session_id
                  ? (sessionNumberById[tx.applied_to_session_id] ?? null)
                  : undefined
              }
            />
          ))}
        </div>
      )}

      {/* "+ Record deposit" button */}
      {canAdmin && (
        <Button
          size="sm"
          onClick={() => setShowRecordDialog(true)}
          className="w-full bg-white/10 hover:bg-white/20 text-[var(--color-bone)] border-0 gap-1.5"
          variant="outline"
        >
          <Plus className="h-3.5 w-3.5" />
          Record deposit
        </Button>
      )}

      {/* ── Record deposit dialog ── */}
      <Dialog open={showRecordDialog} onOpenChange={setShowRecordDialog}>
        <DialogContent className="sm:max-w-sm">
          <DialogHeader>
            <DialogTitle>Record deposit</DialogTitle>
            <DialogDescription>Add a received payment to the project pool.</DialogDescription>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <div className="space-y-1.5">
              <Label>Amount</Label>
              <MoneyInput value={recordAmount} onValueChange={(v) => setRecordAmount(v ?? 0)} placeholder="0.00" />
            </div>
            <div className="space-y-1.5">
              <Label>Method</Label>
              <Select value={recordMethod} onValueChange={(v) => { if (v !== null) setRecordMethod(v as typeof recordMethod) }}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="cash">Cash</SelectItem>
                  <SelectItem value="card">Card</SelectItem>
                  <SelectItem value="stripe">Stripe</SelectItem>
                  <SelectItem value="other">Other</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label>Note (optional)</Label>
              <Input value={recordNote} onChange={(e) => setRecordNote(e.target.value)} placeholder="e.g. Venmo transfer" maxLength={200} />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowRecordDialog(false)}>Cancel</Button>
            <Button onClick={handleRecord} disabled={isPending}>
              {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Record
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* ── Apply to session dialog ── */}
      <Dialog open={showApplyDialog} onOpenChange={setShowApplyDialog}>
        <DialogContent className="sm:max-w-sm">
          <DialogHeader>
            <DialogTitle>Apply deposit to session</DialogTitle>
            <DialogDescription>
              {formatCurrency(poolBalance)} available.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <div className="space-y-1.5">
              <Label>Session</Label>
              <Select value={applyBookingId} onValueChange={(v) => { if (v !== null) setApplyBookingId(v) }}>
                <SelectTrigger><SelectValue placeholder="Select session…" /></SelectTrigger>
                <SelectContent>
                  {availableSessions.map((s) => (
                    <SelectItem key={s.id} value={s.id}>
                      Session {s.session_number ?? '—'} · {formatDate(s.scheduled_at, { month: 'short', day: 'numeric' })}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label>Amount</Label>
              <MoneyInput value={applyAmount} onValueChange={(v) => setApplyAmount(v ?? 0)} placeholder="0.00" />
              <p className="text-xs text-[var(--color-stone)]">Max: {formatCurrency(poolBalance)}</p>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowApplyDialog(false)}>Cancel</Button>
            <Button onClick={handleApply} disabled={isPending}>
              {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Apply
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* ── Consume dialog ── */}
      <Dialog open={showConsumeDialog} onOpenChange={setShowConsumeDialog}>
        <DialogContent className="sm:max-w-sm">
          <DialogHeader>
            <DialogTitle>Write off deposit</DialogTitle>
            <DialogDescription>
              This will zero out the {formatCurrency(poolBalance)} balance. Use for no-shows or forfeitures.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-1.5 py-2">
            <Label>Note (optional)</Label>
            <Input value={consumeNote} onChange={(e) => setConsumeNote(e.target.value)} placeholder="e.g. No-show — Apr 28" maxLength={200} />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowConsumeDialog(false)}>Cancel</Button>
            <Button
              onClick={handleConsume}
              disabled={isPending}
              className="bg-[var(--color-destructive)] text-[var(--color-destructive-foreground)] hover:bg-[var(--color-destructive)]/90"
            >
              {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Write off
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* ── Refund dialog ── */}
      <Dialog open={showRefundDialog} onOpenChange={setShowRefundDialog}>
        <DialogContent className="sm:max-w-sm">
          <DialogHeader>
            <DialogTitle>Record refund</DialogTitle>
            <DialogDescription>
              {formatCurrency(poolBalance)} available to refund.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-1.5 py-2">
            <Label>Amount</Label>
            <MoneyInput value={refundAmount} onValueChange={(v) => setRefundAmount(v ?? 0)} placeholder="0.00" />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowRefundDialog(false)}>Cancel</Button>
            <Button onClick={handleRefund} disabled={isPending}>
              {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Record refund
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

