// ─── Storage URL ───────────────────────────────────────────────────────────────

function getPhotoUrl(storagePath: string): string {
  const base = process.env.NEXT_PUBLIC_SUPABASE_URL ?? ''
  return `${base}/storage/v1/object/public/project-photos/${storagePath}`
}

// ─── Slot definition ───────────────────────────────────────────────────────────

interface TimelineSlot {
  id: string          // unique key for the slot
  label: string       // "Before" / "S1 Fresh" / "S1 Healed" etc.
  kind: ProjectPhotoKind
  bookingId?: string  // session binding (for session-linked slots)
  sessionNumber?: number
  healedDueAt?: Date  // for healed slots — session_date + 6 weeks
  photos: ProjectProgressPhoto[]
}

function buildSlots(
  project: ProjectWithSessions,
  photos: ProjectProgressPhoto[]
): TimelineSlot[] {
  const slots: TimelineSlot[] = []

  // 1. Before
  slots.push({
    id: 'before',
    label: 'Before',
    kind: 'before',
    photos: photos.filter((p) => p.kind === 'before' && !p.booking_id),
  })

  // 2. Per-session: Fresh + Healed
  const sessions = [...project.sessions].sort((a, b) => {
    const na = a.session_number ?? 999
    const nb = b.session_number ?? 999
    return na - nb
  })

  for (const s of sessions) {
    const sn = s.session_number ?? 0
    const label = sn > 0 ? `S${sn}` : 'Session'
    const sessionPhotos = photos.filter((p) => p.booking_id === s.id)

    // Fresh slot
    slots.push({
      id: `session-${s.id}-fresh`,
      label: `${label} Fresh`,
      kind: 'after',
      bookingId: s.id,
      sessionNumber: sn,
      photos: sessionPhotos.filter((p) => p.kind === 'after'),
    })

    // Healed slot
    const sessionDate = new Date(s.scheduled_at)
    const healedDue = new Date(sessionDate)
    healedDue.setDate(healedDue.getDate() + 42) // 6 weeks

    slots.push({
      id: `session-${s.id}-healed`,
      label: `${label} Healed`,
      kind: 'healed',
      bookingId: s.id,
      sessionNumber: sn,
      healedDueAt: healedDue,
      photos: sessionPhotos.filter((p) => p.kind === 'healed'),
    })
  }

  // 3. Loose progress photos (not session-bound)
  const progressPhotos = photos.filter((p) => p.kind === 'progress')
  if (progressPhotos.length > 0 || true) {
    slots.push({
      id: 'progress',
      label: 'Progress',
      kind: 'progress',
      photos: progressPhotos,
    })
  }

  return slots
}

// ─── Lightbox ─────────────────────────────────────────────────────────────────

function Lightbox({
  photos,
  initial,
  contextLabel,
  onClose,
}: {
  photos: ProjectProgressPhoto[]
  initial: number
  contextLabel: string
  onClose: () => void
}) {
  const [idx, setIdx] = useState(initial)
  const photo = photos[idx]

  if (!photo) return null

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-[var(--color-onyx)]/90"
      onClick={onClose}
    >
      <button
        onClick={onClose}
        className="absolute top-4 right-4 p-2 rounded-full bg-white/10 text-[var(--color-bone)] hover:bg-white/20"
        aria-label="Close"
      >
        <X className="h-5 w-5" />
      </button>

      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={getPhotoUrl(photo.storage_path)}
        alt={photo.caption ?? contextLabel}
        className="max-h-[85vh] max-w-[90vw] object-contain rounded-lg"
        onClick={(e) => e.stopPropagation()}
      />

      <div className="absolute bottom-6 left-0 right-0 flex items-center justify-center gap-3">
        {photos.length > 1 && (
          <>
            <button
              onClick={(e) => { e.stopPropagation(); setIdx((i) => Math.max(0, i - 1)) }}
              disabled={idx === 0}
              className="px-3 py-1.5 rounded-lg bg-white/10 text-[var(--color-bone)] text-sm disabled:opacity-30 hover:bg-white/20"
            >
              ← Prev
            </button>
            <span className="text-xs text-[var(--color-stone)]">
              {idx + 1} / {photos.length}
            </span>
            <button
              onClick={(e) => { e.stopPropagation(); setIdx((i) => Math.min(photos.length - 1, i + 1)) }}
              disabled={idx === photos.length - 1}
              className="px-3 py-1.5 rounded-lg bg-white/10 text-[var(--color-bone)] text-sm disabled:opacity-30 hover:bg-white/20"
            >
              Next →
            </button>
          </>
        )}
      </div>

      {/* Caption */}
      <div className="absolute bottom-16 left-0 right-0 text-center">
        <p className="text-xs text-[var(--color-stone)]">{contextLabel}</p>
        {photo.caption && (
          <p className="text-sm text-[var(--color-bone)] mt-0.5">{photo.caption}</p>
        )}
        {photo.taken_at && (
          <p className="text-xs text-[var(--color-stone)] mt-0.5">
            {formatDate(photo.taken_at, { month: 'short', day: 'numeric', year: 'numeric' })}
          </p>
        )}
      </div>
    </div>
  )
}

// ─── Photo slot ───────────────────────────────────────────────────────────────

function PhotoSlot({
  slot,
  canWrite,
  onUpload,
  onRemove,
  onOpenLightbox,
  isUploadingThis,
  isPending,
}: {
  slot: TimelineSlot
  canWrite: boolean
  onUpload: (slot: TimelineSlot, files: File[]) => void
  onRemove: (photoId: string) => void
  onOpenLightbox: (photos: ProjectProgressPhoto[], idx: number, label: string) => void
  isUploadingThis: boolean
  isPending: boolean
}) {
  const now = new Date()
  const isHealedOverdue =
    slot.kind === 'healed' &&
    slot.photos.length === 0 &&
    slot.healedDueAt != null &&
    slot.healedDueAt < now

  const hasPhotos = slot.photos.length > 0
  const firstPhoto = slot.photos[0]

  return (
    <div className="shrink-0 flex flex-col gap-1.5 w-28">
      <span className="text-[11px] font-medium text-[var(--color-stone)] truncate">{slot.label}</span>

      {/* Photo tile or placeholder */}
      <div
        className={cn(
          'relative w-28 h-28 rounded-lg overflow-hidden border',
          hasPhotos
            ? 'border-[var(--color-border)] cursor-pointer group'
            : 'border-dashed border-[var(--color-border)]',
          isHealedOverdue && 'border-[var(--color-rust)]/50'
        )}
      >
        {hasPhotos && firstPhoto ? (
          <>
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={getPhotoUrl(firstPhoto.storage_path)}
              alt={firstPhoto.caption ?? slot.label}
              className="h-full w-full object-cover group-hover:opacity-90 transition-opacity"
              onClick={() => onOpenLightbox(slot.photos, 0, slot.label)}
            />
            {slot.photos.length > 1 && (
              <span className="absolute bottom-1 right-1 bg-[var(--color-onyx)]/70 text-[var(--color-bone)] text-[10px] px-1.5 py-0.5 rounded">
                +{slot.photos.length - 1}
              </span>
            )}
            {canWrite && (
              <button
                onClick={() => onRemove(firstPhoto.id)}
                className="absolute top-1 right-1 p-1 rounded bg-[var(--color-onyx)]/50 text-[var(--color-bone)] opacity-0 group-hover:opacity-100 hover:bg-[var(--color-destructive)] transition-all"
                aria-label="Remove photo"
              >
                <Trash2 className="h-2.5 w-2.5" />
              </button>
            )}
          </>
        ) : (
          <div className="flex flex-col items-center justify-center h-full gap-1">
            {isHealedOverdue ? (
              <div className="flex flex-col items-center gap-1 px-1 text-center">
                <span className="w-2 h-2 rounded-full bg-[var(--color-rust)]" />
                <span className="text-[10px] text-[var(--color-stone)] leading-tight">
                  Healed photo due
                </span>
              </div>
            ) : (
              <Camera className="h-5 w-5 text-[var(--color-stone)]/40" />
            )}
          </div>
        )}
      </div>

      {/* Upload button */}
      {canWrite && (
        <FileDropzone
          accept={{ 'image/*': ['.jpg', '.jpeg', '.png', '.webp'] }}
          maxSize={10 * 1024 * 1024}
          maxFiles={1}
          onFilesAccepted={(files) => onUpload(slot, files)}
          loading={isUploadingThis}
          disabled={isPending}
          className="h-auto py-1 text-[10px]"
        >
          <div className="flex items-center justify-center gap-1 text-[var(--color-stone)]">
            <Plus className="h-3 w-3" />
            <span>Add</span>
          </div>
        </FileDropzone>
      )}
    </div>
  )
}

// ─── Main timeline ─────────────────────────────────────────────────────────────

interface PhotoProgressionTimelineProps {
  project: ProjectWithSessions
  photos: ProjectProgressPhoto[]
  role: string
  onRefresh: () => void
}

export function PhotoProgressionTimeline({
  project,
  photos,
  role,
  onRefresh,
}: PhotoProgressionTimelineProps) {
  const [isPending, startTransition] = useTransition()
  const [uploadingSlotId, setUploadingSlotId] = useState<string | null>(null)
  const [removingId, setRemovingId] = useState<string | null>(null)
  const [lightbox, setLightbox] = useState<{
    photos: ProjectProgressPhoto[]
    idx: number
    label: string
  } | null>(null)

  const canWrite = role === 'owner' || role === 'admin' || role === 'artist'

  const slots = buildSlots(project, photos)

  const handleUpload = (slot: TimelineSlot, files: File[]) => {
    const file = files[0]
    if (!file) return
    setUploadingSlotId(slot.id)
    startTransition(async () => {
      const fd = new FormData()
      fd.append('file', file)
      fd.set('kind', slot.kind)
      if (slot.bookingId) fd.set('bookingId', slot.bookingId)

      const result = await addProgressPhotoAction(project.id, fd)
      setUploadingSlotId(null)
      if (!result.ok) { toast.error(result.error); return }
      toast.success('Photo added')
      onRefresh()
    })
  }

  const handleRemove = (photoId: string) => {
    startTransition(async () => {
      const result = await removeProgressPhotoAction(project.id, photoId)
      if (!result.ok) { toast.error(result.error); return }
      toast.success('Photo removed')
      onRefresh()
    })
    setRemovingId(null)
  }

  return (
    <div className="space-y-4">
      {/* Actions row */}
      <div className="flex items-center justify-between">
        <p className="text-xs text-[var(--color-stone)]">
          {photos.length} photo{photos.length !== 1 ? 's' : ''} across {project.sessions.length} session{project.sessions.length !== 1 ? 's' : ''}
        </p>
        <div className="flex items-center gap-2">
          <button
            onClick={() => toast.info('Download ZIP — coming in v2')}
            className="text-xs text-[var(--color-stone)] hover:text-[var(--color-onyx)] transition-colors"
          >
            Download all
          </button>
        </div>
      </div>

      {/* Horizontal scrollable strip */}
      <div className="flex gap-4 overflow-x-auto pb-2 scrollbar-thin scrollbar-thumb-[var(--color-border)]">
        {slots.map((slot) => (
          <PhotoSlot
            key={slot.id}
            slot={slot}
            canWrite={canWrite}
            onUpload={handleUpload}
            onRemove={(id) => setRemovingId(id)}
            onOpenLightbox={(p, idx, lbl) => setLightbox({ photos: p, idx, label: lbl })}
            isUploadingThis={uploadingSlotId === slot.id}
            isPending={isPending}
          />
        ))}
      </div>

      {/* Remove confirmation */}
      <AlertDialog open={removingId !== null} onOpenChange={(open) => !open && setRemovingId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Remove this photo?</AlertDialogTitle>
            <AlertDialogDescription>
              The photo will be permanently removed from the project. This cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => removingId && handleRemove(removingId)}
              disabled={isPending}
              className="bg-[var(--color-destructive)] text-[var(--color-destructive-foreground)] hover:bg-[var(--color-destructive)]/90"
            >
              Remove
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Lightbox */}
      {lightbox && (
        <Lightbox
          photos={lightbox.photos}
          initial={lightbox.idx}
          contextLabel={lightbox.label}
          onClose={() => setLightbox(null)}
        />
      )}
    </div>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { toast } from 'sonner'
import {
  Activity,
  DollarSign,
  Calendar,
  Camera,
  StickyNote,
  ArrowRight,
  Send,
  Loader2,
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { cn, formatRelativeTime, formatCurrency } from '@/lib/utils'
import { addProjectNoteAction } from '@/app/(app)/projects/actions'
import type { ProjectActivityLogEntry } from '@/lib/projects/queries'
import type { Json } from '@/lib/supabase/types'

// ─── Event type filters ────────────────────────────────────────────────────────

type EventFilter = 'all' | 'deposits' | 'sessions' | 'status' | 'notes' | 'photos'

const FILTER_OPTIONS: { value: EventFilter; label: string }[] = [
  { value: 'all', label: 'All events' },
  { value: 'deposits', label: 'Deposits' },
  { value: 'sessions', label: 'Sessions' },
  { value: 'status', label: 'Status changes' },
  { value: 'notes', label: 'Notes' },
  { value: 'photos', label: 'Photos' },
]

function matchesFilter(eventType: string, filter: EventFilter): boolean {
  if (filter === 'all') return true
  if (filter === 'deposits') return eventType === 'deposit_received' || eventType === 'deposit_applied'
  if (filter === 'sessions') return eventType === 'session_completed' || eventType === 'created'
  if (filter === 'status') return eventType === 'status_changed'
  if (filter === 'notes') return eventType === 'note_added'
  if (filter === 'photos') return eventType === 'photo_uploaded'
  return true
}

// ─── Event icon ───────────────────────────────────────────────────────────────

function eventIcon(eventType: string) {
  switch (eventType) {
    case 'deposit_received':
    case 'deposit_applied':
      return <DollarSign className="h-3.5 w-3.5" />
    case 'session_completed':
      return <Calendar className="h-3.5 w-3.5" />
    case 'photo_uploaded':
      return <Camera className="h-3.5 w-3.5" />
    case 'note_added':
      return <StickyNote className="h-3.5 w-3.5" />
    case 'status_changed':
      return <ArrowRight className="h-3.5 w-3.5" />
    default:
      return <Activity className="h-3.5 w-3.5" />
  }
}

// ─── Event description ────────────────────────────────────────────────────────

function safeDetails(raw: Json | null): Record<string, unknown> {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return {}
  return raw as Record<string, unknown>
}

function eventDescription(entry: ProjectActivityLogEntry): string {
  const d = safeDetails(entry.details)

  switch (entry.event_type) {
    case 'created':
      return 'Project created'
    case 'status_changed': {
      const from = String(d.prev_status ?? '').replace(/_/g, ' ')
      const to = String(d.new_status ?? '').replace(/_/g, ' ')
      return `Status changed: ${from} → ${to}`
    }
    case 'deposit_received': {
      const amt = typeof d.amount_cents === 'number' ? formatCurrency(d.amount_cents) : ''
      const method = d.method ? ` via ${d.method}` : ''
      return `Deposit received${method} ${amt}`.trim()
    }
    case 'deposit_applied': {
      const amt = typeof d.amount_cents === 'number' ? formatCurrency(d.amount_cents) : ''
      return `Applied ${amt} to session`
    }
    case 'session_completed': {
      const sn = d.session_number != null ? ` S${d.session_number}` : ''
      return `Session${sn} completed`
    }
    case 'photo_uploaded': {
      const kind = d.kind ? ` · ${String(d.kind)}` : ''
      return `Photo added${kind}`
    }
    case 'note_added':
      return typeof d.body === 'string' ? d.body : 'Note added'
    default:
      return entry.event_type.replace(/_/g, ' ')
  }
}

// ─── Timeline entry ───────────────────────────────────────────────────────────

function ActivityEntry({ entry }: { entry: ProjectActivityLogEntry }) {
  const isNote = entry.event_type === 'note_added'
  const actorName = entry.actor?.full_name ?? 'Studio'
  const relTime = formatRelativeTime(entry.created_at)

  return (
    <div className="flex gap-3 py-3 border-b border-[var(--color-border)] last:border-0">
      {/* Icon dot */}
      <div
        className={cn(
          'mt-0.5 shrink-0 w-6 h-6 rounded-full flex items-center justify-center',
          isNote
            ? 'bg-[var(--color-stone)]/10 text-[var(--color-stone)]'
            : 'bg-[var(--color-onyx)]/5 text-[var(--color-stone)]'
        )}
      >
        {eventIcon(entry.event_type)}
      </div>

      {/* Content */}
      <div className="flex-1 min-w-0">
        <p className={cn(
          'text-sm text-[var(--color-onyx)]',
          isNote && 'italic',
        )}>
          {eventDescription(entry)}
        </p>
        <p className="text-[11px] text-[var(--color-stone)] mt-0.5">
          {actorName} · {relTime}
        </p>
      </div>
    </div>
  )
}

// ─── Props ────────────────────────────────────────────────────────────────────

interface ProjectActivityTabProps {
  projectId: string
  activity: ProjectActivityLogEntry[]
  onRefresh: () => void
}

// ─── Tab ──────────────────────────────────────────────────────────────────────

export function ProjectActivityTab({
  projectId,
  activity,
  onRefresh,
}: ProjectActivityTabProps) {
  const [filter, setFilter] = useState<EventFilter>('all')
  const [noteBody, setNoteBody] = useState('')
  const [isPending, startTransition] = useTransition()

  const filtered = activity.filter((e) => matchesFilter(e.event_type, filter))

  const handleAddNote = () => {
    if (!noteBody.trim()) return
    startTransition(async () => {
      const result = await addProjectNoteAction(projectId, noteBody)
      if (!result.ok) {
        toast.error(result.error)
        return
      }
      setNoteBody('')
      onRefresh()
    })
  }

  return (
    <div className="space-y-4 max-w-xl">
      {/* Filter */}
      <div className="flex items-center gap-2">
        <Select value={filter} onValueChange={(v) => { if (v !== null) setFilter(v as EventFilter) }}>
          <SelectTrigger className="w-44 h-8 text-sm">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {FILTER_OPTIONS.map((o) => (
              <SelectItem key={o.value} value={o.value}>{o.label}</SelectItem>
            ))}
          </SelectContent>
        </Select>
        <span className="text-xs text-[var(--color-stone)]">
          {filtered.length} event{filtered.length !== 1 ? 's' : ''}
        </span>
      </div>

      {/* Timeline */}
      {filtered.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-12 rounded-lg border border-dashed border-[var(--color-border)] text-center">
          <Activity className="h-10 w-10 text-[var(--color-stone)]/40 mb-3" />
          <p className="text-sm font-medium text-[var(--color-onyx)] mb-1">
            <em>No events yet.</em>
          </p>
          <p className="text-xs text-[var(--color-stone)] max-w-[220px]">
            Activity is recorded as sessions, deposits, and status changes happen.
          </p>
        </div>
      ) : (
        <div className="divide-y-0">
          {filtered.map((entry) => (
            <ActivityEntry key={entry.id} entry={entry} />
          ))}
        </div>
      )}

      {/* Internal notes thread */}
      <div className="pt-2 border-t border-[var(--color-border)] space-y-2">
        <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)]">
          Internal note
        </p>
        <div className="flex gap-2 items-end">
          <Textarea
            value={noteBody}
            onChange={(e) => setNoteBody(e.target.value)}
            placeholder="Add an internal note…"
            rows={2}
            maxLength={2000}
            className="resize-none text-sm flex-1"
            onKeyDown={(e) => {
              if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
                e.preventDefault()
                handleAddNote()
              }
            }}
          />
          <Button
            size="icon"
            onClick={handleAddNote}
            disabled={isPending || !noteBody.trim()}
            className="h-9 w-9 shrink-0"
            aria-label="Add note"
          >
            {isPending ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <Send className="h-4 w-4" />
            )}
          </Button>
        </div>
        <p className="text-[11px] text-[var(--color-stone)]">⌘ Enter to submit · Internal only</p>
      </div>
    </div>
  )
}

