/**
 * Get the next upcoming session for a project (scheduled_at > now, ASC).
 */
export async function getNextSessionForProject(
  studioId: string,
  projectId: string
): Promise<ProjectSession | null> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('bookings')
    .select(`
      id, scheduled_at, session_number, status, price_cents,
      deposit_paid, deposit_cents,
      service:services!bookings_service_id_fkey(id, name, color),
      artist:artists!bookings_artist_id_fkey(id, display_name, avatar_url)
    `)
    .eq('project_id', projectId)
    .eq('studio_id', studioId)
    .gt('scheduled_at', new Date().toISOString())
    .order('scheduled_at', { ascending: true })
    .limit(1)
    .maybeSingle()

  if (error) {
    logger.error({ error, projectId }, 'getNextSessionForProject failed')
    return null
  }

  if (!data) return null

  return {
    id: data.id,
    scheduled_at: data.scheduled_at,
    session_number: data.session_number,
    status: data.status,
    price_cents: data.price_cents,
    deposit_paid: data.deposit_paid,
    deposit_cents: data.deposit_cents,
    service: Array.isArray(data.service) ? (data.service[0] ?? null) : (data.service ?? null),
    artist: Array.isArray(data.artist) ? (data.artist[0] ?? null) : (data.artist ?? null),
  }
}

/**
 * Get deposit transactions for a project, newest first.
 */
export async function listDepositTransactions(
  _studioId: string,
  projectId: string
): Promise<ProjectDepositTransactionRow[]> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('project_deposit_transactions' as 'projects')
    .select('*')
    .eq('project_id' as never, projectId)
    .order('created_at' as never, { ascending: false })

  if (error) {
    logger.error({ error, projectId }, 'listDepositTransactions failed — returning empty')
    return []
  }

  return (data ?? []) as unknown as ProjectDepositTransactionRow[]
}

/**
 * Get activity log for a project, newest first, with actor profile.
 */
export interface ProjectActivityLogEntry extends ProjectActivityLogRow {
  actor: { full_name: string | null; avatar_url: string | null } | null
}

export async function listProjectActivity(
  _studioId: string,
  projectId: string
): Promise<ProjectActivityLogEntry[]> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('project_activity_log' as 'projects')
    .select('*, actor:profiles!project_activity_log_actor_id_fkey(full_name, avatar_url)' as never)
    .eq('project_id' as never, projectId)
    .order('created_at' as never, { ascending: false })
    .limit(100)

  if (error) {
    logger.error({ error, projectId }, 'listProjectActivity failed — returning empty')
    return []
  }

  return (data ?? []).map((row: Record<string, unknown>) => {
    const { actor, ...rest } = row
    return {
      ...(rest as unknown as ProjectActivityLogRow),
      actor: (actor as { full_name: string | null; avatar_url: string | null } | null) ?? null,
    }
  })
}

